// Lesson data: every ./*.json in this folder (generated by scripts/*.mjs, then committed).
// Full lessons are code-split, one chunk per lesson, loaded by loadLesson() (../index.ts); a small eager
// projection of each (LessonMeta, built by the lesson-data Vite plugin) serves everything that needs all lessons.
// JSON imports are structurally widened (string instead of literal unions), hence the casts;
// content.test.ts validates every lesson against the schema and registries.
import type { Lesson } from "../../types/lesson";
import type { LessonMeta } from "../derive";

const idOf = (path: string) => path.replace(/^.*\/|\.json(\?.*)?$/g, "");

/** Lesson id → chunk loader (file name = lesson id, checked by content.test.ts). */
export const LOADERS: Record<string, () => Promise<Lesson>> = Object.fromEntries(
  Object.entries(import.meta.glob<Lesson>("./*.json", { import: "default" })).map(([path, load]) => [idOf(path), load]),
);

/** Lesson id → metadata, for every lesson file. */
export const META: Record<string, LessonMeta> = Object.fromEntries(
  Object.values(import.meta.glob<LessonMeta>("./*.json", { query: "?lesson-meta", import: "default", eager: true })).map(
    (m) => [m.id, m],
  ),
);
